import java.util.*;
import java.io.*;

public class Main {
    static int[] tree;
    static int n, mod;
    static int[] fact;

    static int makeTree(int n) {
        int i = 2;
        while (true) {
            if (i >= n * 2) {
                return i;
            } else {
                i *= 2;
            }
        }
    }

    static void update(int i, int x) {
        i += tree.length / 2;
        tree[i] = x;
        i /= 2;
        while (i > 0) {
            tree[i] = tree[2 * i] + tree[2 * i + 1];
            i /= 2;
        }
    }

    static int getSum(int s, int t) {
        s += tree.length / 2;
        t += tree.length / 2;
        int ans = 0;
        while (s <= t) {
            if (s % 2 == 0) s /= 2;
            else {
                ans += tree[s];
                s = (s + 1) / 2;
            }
            if (t % 2 == 1) t /= 2;
            else {
                ans += tree[t];
                t = (t - 1) / 2;
            }
        }
        return ans;
    }

    static List<Integer> primeFactorize(int n) {
        List<Integer> ans = new ArrayList<>();
        for (int i = 2; i * i <= n; i++) {
            while (n % i == 0) {
                ans.add(i);
                n /= i;
            }
            if (n == 1) break;
        }
        if (n != 1) ans.add(n);
        return ans;
    }

    static int eulerFunc(int n) {
        Set<Integer> p = new HashSet<>(primeFactorize(n));
        int x = n;
        for (int i : p) {
            x = x / i * (i - 1);
        }
        return x;
    }

    static int f(int a, int b) {
        long ans = 1;
        for (int i = a; i <= b; i++) {
            ans = (ans * i) % mod;
        }
        return (int) ans;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        int x = eulerFunc(mod);
        int l = n + 5;
        fact = new int[l + 1];
        fact[0] = 1;
        for (int i = 1; i <= l; i++) {
            fact[i] = (int)((long)i * fact[i - 1] % mod);
        }
        long ans;
        if (n <= 3) {
            ans = 0;
        } else {
            int[] dp = new int[2000];
            dp[0] = 1;
            dp[1] = 2;
            dp[2] = 2;
            dp[3] = 1;

            tree = new int[makeTree(2005)];
            for (int i = 0; i < 4; i++) {
                update(i, dp[i]);
            }

            int m = 3;
            ans = 0;

            for (int i = 0; i < n - 3; i++) {
                int[] dp0 = Arrays.copyOf(dp, dp.length);
                int ans0 = 0;
                for (int j = 0; j <= i + 3; j++) {
                    for (int k = 1; k <= m + 1; k++) {
                        int sumVal = getSum(j + k + 1, 2004);
                        ans0 += (int)((long)sumVal * dp0[k - 1] % mod);
                        ans0 %= mod;
                        dp[j + k] = (dp[j + k] + dp0[k - 1]) % mod;
                        update(j + k, dp[j + k]);
                    }
                }
                m += i + 3;
                long term = ((long)f(i + 4, n) * ans0) % mod;
                ans = (ans + term) % mod;
            }
        }
        System.out.println(ans);
    }
}

